import { Image, StyleSheet, View } from "react-native";

type EloLogoProps = {
  compact?: boolean;
};

export const ELO_LOGO_DATA_URI = "data:image/png;base64,";

export function EloLogo({ compact = false }: EloLogoProps) {
  return (
    <View style={[styles.wrap, compact && styles.compactWrap]}>
      <Image
        accessibilityLabel="Nethanel Elo"
        source={{ uri: ELO_LOGO_DATA_URI }}
        resizeMode="contain"
        style={[styles.image, compact && styles.compactImage]}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    width: 220,
    height: 74,
    alignItems: "flex-start",
    justifyContent: "center",
  },

  compactWrap: {
    width: 138,
    height: 48,
  },

  image: {
    width: "100%",
    height: "100%",
  },

  compactImage: {
    width: "100%",
    height: "100%",
  },
});
